import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o as s,X as t}from"./chunks/vendor-vueuse.XPft87tp.js";const v=JSON.parse('{"title":"Vue 项目脚手架：从 Vue CLI 到 create-vue","description":"","frontmatter":{},"headers":[],"relativePath":"vue/vue-cli-scaffold.md","filePath":"vue/vue-cli-scaffold.md","lastUpdated":1786990830000}'),l={name:"vue/vue-cli-scaffold.md"};function c(u,e,r,n,p,o){return s(),i("div",null,e[0]||(e[0]=[t(`<h1 id="vue-项目脚手架-从-vue-cli-到-create-vue" tabindex="-1">Vue 项目脚手架：从 Vue CLI 到 create-vue <a class="header-anchor" href="#vue-项目脚手架-从-vue-cli-到-create-vue" aria-label="Permalink to &quot;Vue 项目脚手架：从 Vue CLI 到 create-vue&quot;">​</a></h1><h3 id="为什么需要脚手架" tabindex="-1">为什么需要脚手架 <a class="header-anchor" href="#为什么需要脚手架" aria-label="Permalink to &quot;为什么需要脚手架&quot;">​</a></h3><p>直接在 HTML 中用 <code>&lt;script&gt;</code> 引入 Vue CDN 确实能跑起来，但在实际项目中这样做会很快遇到瓶颈：</p><ul><li>无法使用单文件组件（<code>.vue</code>），所有逻辑、模板和样式挤在一起</li><li>不支持 TypeScript 和现代 ES 语法（需要手动配置 Babel）</li><li>缺乏热更新，每次修改都要手动刷新浏览器</li><li>缺乏代码分割和打包优化，首屏加载体积不可控</li><li>无法统一管理项目结构、lint 规则和测试框架</li></ul><p>脚手架的价值在于把上述配置工作标准化：一条命令就能生成一个已经配好 Webpack/Vite、Babel、TypeScript、ESLint、路由、状态管理的项目骨架，开发者可以直接开始写业务代码。</p><h3 id="vue-cli" tabindex="-1">Vue CLI <a class="header-anchor" href="#vue-cli" aria-label="Permalink to &quot;Vue CLI&quot;">​</a></h3><p>Vue CLI 是 Vue 2 时代的官方脚手架，底层基于 Webpack。它的特点是生态成熟、插件体系丰富。安装后通过 <code>vue create</code> 交互式选择项目配置：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @vue/cli</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vue</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-project</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Vue CLI 会在创建过程中让开发者选择 Vue 版本、是否使用 TypeScript、CSS 预处理器、测试框架、ESLint 等，最终生成一个完整的项目模板。项目结构包括了 <code>src/</code>、<code>public/</code>、<code>vue.config.js</code> 等标准目录和文件。</p><p>Webpack 的缺点在于开发和构建速度——随着项目规模增长，冷启动和热更新会逐渐变慢。尽管 Vue CLI 通过 DLL 预编译、缓存等手段做了优化，但底层架构的限制无法完全消除。</p><h3 id="create-vue-vue-官方推荐" tabindex="-1">create-vue（Vue 官方推荐） <a class="header-anchor" href="#create-vue-vue-官方推荐" aria-label="Permalink to &quot;create-vue（Vue 官方推荐）&quot;">​</a></h3><p>Vue 3 的官方脚手架从 Vue CLI 转向了基于 Vite 的 <code>create-vue</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vue@latest</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>底层的 Vite 利用了浏览器原生 ES Module 的能力：开发模式下不需要打包，浏览器直接按需加载 <code>.vue</code> 和 <code>.ts</code> 文件，由 Vite 开发服务器实时编译后返回。配合 esbuild 做预构建（将 CommonJS 模块转为 ESM），冷启动时间从&quot;等十几秒&quot;变成了&quot;几乎瞬间&quot;。</p><p>热更新方面，Vite 按需编译，只更新改动的模块，不重新打包整个应用，速度快得多。</p><h3 id="vue-cli-与-create-vue-的定位关系" tabindex="-1">Vue CLI 与 create-vue 的定位关系 <a class="header-anchor" href="#vue-cli-与-create-vue-的定位关系" aria-label="Permalink to &quot;Vue CLI 与 create-vue 的定位关系&quot;">​</a></h3><p><code>create-vue</code> 定位为&quot;轻量脚手架&quot;——只提供基础的项目模板和最常用的配置选项，不像 Vue CLI 拥有庞大的插件市场。如果项目需要复杂的 Webpack 配置（比如自定义 loader）、需要使用 Vue 2，或者大量的 Vue CLI 插件生态依赖，Vue CLI 仍然是合理选择。</p><p>对于新启动的 Vue 3 项目，官方推荐的路径是使用 <code>create-vue</code> + Vite。如果有特殊需求无法满足，可以从这个模板出发手动扩展。</p>`,18)]))}const k=a(l,[["render",c]]);export{v as __pageData,k as default};
